BOUNDARY='\n// Adapters: UIKit pixels/JPEG encoder, Telegram resource models and temp-file I/O.\n// Production decides the supplied encoder quality, HD flag and output dimensions.\npublic struct PixelDimensions {\n public var width:Int32; public var height:Int32\n public init(_ size:CGSize){width=Int32(size.width);height=Int32(size.height)}\n public init(width:Int32,height:Int32){self.width=width;self.height=height}\n public var cgSize:CGSize{CGSize(width:CGFloat(width),height:CGFloat(height))}\n}\nextension CGSize {\n func aspectFittedOrSmaller(_ maxSize:CGSize)->CGSize {\n  let factor=min(1,min(maxSize.width/width,maxSize.height/height))\n  return CGSize(width:floor(width*factor),height:floor(height*factor))\n }\n}\nfinal class UIImage {let size:CGSize;init(_ size:CGSize){self.size=size}}\nprotocol Resource {}\nstruct LocalFileReferenceMediaResource:Resource {let localFilePath:String;let randomId:Int64}\nstruct PhotoLibraryMediaResource:Resource {\n let localIdentifier:String;let uniqueId:Int64;let quality:Int32?;let forceHd:Bool\n init(localIdentifier:String,uniqueId:Int64,quality:Int32?=nil,forceHd:Bool){self.localIdentifier=localIdentifier;self.uniqueId=uniqueId;self.quality=quality;self.forceHd=forceHd}\n}\nenum EngineMediaResource {struct Id{}}\nenum Namespaces {enum Media {static let LocalImage:Int32=1}}\nenum EngineMedia {struct Id {let namespace:Int32;let id:Int64}}\nstruct TelegramMediaImageRepresentation {\n let dimensions:PixelDimensions;let resource:Resource;let progressiveSizes:[Int32]\n let immediateThumbnailData:Data?;let hasVideo:Bool;let isPersonal:Bool\n}\nstruct TelegramMediaImageFlags:OptionSet {\n let rawValue:Int\n static let hasStickers=Self(rawValue:1);static let isLivePhoto=Self(rawValue:2)\n}\nfinal class TelegramMediaFile: EngineRawMedia {}\nstruct TelegramMediaImage: EngineRawMedia {\n let imageId:EngineMedia.Id;let representations:[TelegramMediaImageRepresentation]\n let immediateThumbnailData:Data?;let reference:Int?;let partialReference:Int?\n let flags:TelegramMediaImageFlags;var video:TelegramMediaFile?=nil\n}\nfinal class EngineTempBox {\n struct File {let path:String}\n static let shared=EngineTempBox()\n func tempFile(fileName:String)->File{File(path:NSTemporaryDirectory()+UUID().uuidString)}\n func dispose(_ file:File){}\n}\nvar suppliedEncoderQuality:Float?\nfunc compressImageToJPEG(_ image:UIImage,quality:Float,tempFilePath:String)->Data?{suppliedEncoderQuality=quality;return Data([1])}\nfunc TGScaleImageToPixelSize(_ image:UIImage,_ size:CGSize)->UIImage?{UIImage(size)}\nfunc chatMediaSendThumbnailRepresentation(thumbnail:UIImage,fittedTo:CGSize,storeResourceData:(EngineMediaResource.Id,Data)->Void)->TelegramMediaImageRepresentation?{nil}\n\nprotocol EngineRawMedia {}\nenum MediaQualityPreset {case videoMessage}\nstruct MediaEditorValues {var qualityPreset:MediaQualityPreset?;var originalDimensions=PixelDimensions(width:4000,height:3000)}\nstruct ChatMediaSendConvertedGif {}\nstruct ChatMediaSendPreparedLivePhoto {}\nstruct ChatMediaSendPreparedAnimatedPhoto {}\nenum ChatMediaSendLivePhotoMode {case off,live,loop}\nfunc chatMediaEditorCroppedNominalDimensions(values:MediaEditorValues)->PixelDimensions{values.originalDimensions}\nfunc nagramiXCompressImageToJPEG(_ image:UIImage,quality:Float,tempFilePath:String)->Data?{suppliedEncoderQuality=quality;return Data([2])}\n'
